create table public.platform_roles(user_id uuid primary key references auth.users(id) on delete cascade,role text not null check(role in ('super_admin','content_editor','translator','assessment_reviewer','partner_verifier','trust_safety','ai_governance','support')),active boolean not null default true,created_at timestamptz not null default now());
create table public.external_resources(id uuid primary key default gen_random_uuid(),provider text not null check(provider in ('youtube','google_drive')),external_id text not null,title_en text not null,title_hi text,language text not null,owner_name text not null,owner_contact text,embed_url text not null,privacy_mode boolean not null default true,captions_available boolean not null default false,text_fallback text,permission_status text not null default 'pending' check(permission_status in ('pending','valid','broken','revoked')),review_status text not null default 'draft' check(review_status in ('draft','technical_review','translation_review','approved','rejected','deprecated')),reviewed_by uuid references auth.users(id),reviewed_at timestamptz,next_review_at timestamptz,metadata jsonb not null default '{}',unique(provider,external_id));
create table public.content_revisions(id uuid primary key default gen_random_uuid(),resource_id uuid not null references public.external_resources(id) on delete cascade,version integer not null,content_en jsonb not null,content_hi jsonb,change_note text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(resource_id,version));
create table public.prompt_versions(id uuid primary key default gen_random_uuid(),prompt_key text not null,version text not null,system_template text not null,input_schema jsonb not null,output_schema jsonb not null,model_key text not null,status text not null check(status in ('draft','evaluation','approved','production','retired')),evaluation_summary jsonb not null default '{}',created_by uuid not null references auth.users(id),approved_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(prompt_key,version));
create table public.feature_flags(key text primary key,description text not null,enabled boolean not null default false,rollout_percent smallint not null default 0 check(rollout_percent between 0 and 100),audience jsonb not null default '{}',risk_tier text not null check(risk_tier in ('low','medium','high')),updated_by uuid not null references auth.users(id),updated_at timestamptz not null default now());
create table public.partner_verification_cases(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),assigned_to uuid references auth.users(id),checks jsonb not null default '{}',risk_rating text check(risk_rating in ('low','medium','high')),status text not null default 'pending' check(status in ('pending','reviewing','verified','rejected','suspended')),decision_note text,created_at timestamptz not null default now(),decided_at timestamptz);
create function public.is_platform_staff() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.platform_roles r where r.user_id=auth.uid() and r.active)$$;
alter table public.platform_roles enable row level security;alter table public.external_resources enable row level security;alter table public.content_revisions enable row level security;alter table public.prompt_versions enable row level security;alter table public.feature_flags enable row level security;alter table public.partner_verification_cases enable row level security;
create policy "staff read roles" on public.platform_roles for select using(user_id=auth.uid() or public.is_platform_staff());
create policy "approved resources public" on public.external_resources for select using(review_status='approved' or public.is_platform_staff());
create policy "staff manage resources" on public.external_resources for all using(public.is_platform_staff()) with check(public.is_platform_staff());
create policy "staff manage revisions" on public.content_revisions for all using(public.is_platform_staff()) with check(public.is_platform_staff());
create policy "staff manage prompts" on public.prompt_versions for all using(public.is_platform_staff()) with check(public.is_platform_staff());
create policy "staff read flags" on public.feature_flags for select using(public.is_platform_staff());
create policy "staff manage flags" on public.feature_flags for all using(public.is_platform_staff()) with check(public.is_platform_staff());
create policy "staff manage partner verification" on public.partner_verification_cases for all using(public.is_platform_staff()) with check(public.is_platform_staff());
create index resources_review_idx on public.external_resources(review_status,next_review_at);create index partner_verification_queue_idx on public.partner_verification_cases(status,created_at);
